/**
 * 2C ORACLE — the parse speed work must not change a byte of what a scan emits.
 *
 * Every directory under `test/fixtures/` is scanned (the list is derived, so a
 * fixture added tomorrow is covered without anyone editing this file). Two
 * fingerprints per fixture are compared with `scan-oracle.golden.json`, which was
 * generated by the serial, uncached code BEFORE any speed change:
 *
 *   graph  sha256 of JSON.stringify(graph) with `scannedAt` removed
 *   facts  sha256 of the per-service FileFacts the parse produced (every field,
 *          Maps expanded, source `lines` included), in walk order
 *
 * The facts hash is what makes the oracle strict: a changed traversal that happens
 * to leave the graph alone (a dropped env read, a reordered call) still moves it.
 *
 * Regenerate only when the OLD output is proven wrong: SEQ_ORACLE_UPDATE=1.
 */
import assert from 'node:assert';
import { test } from 'node:test';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { scanRepo, type ScanOptions } from '../scan.js';
import type { FileFacts } from '../types.js';

const here = path.dirname(fileURLToPath(import.meta.url));
export const FIXTURES = path.resolve(here, '..', '..', 'test', 'fixtures');
const GOLDEN = path.join(FIXTURES, 'scan-oracle.golden.json');

export function fixtureNames(): string[] {
  return fs
    .readdirSync(FIXTURES, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .sort();
}

const sha = (s: string): string => crypto.createHash('sha256').update(s).digest('hex');

function canon(v: unknown): string {
  return JSON.stringify(v, (_k, x) => (x instanceof Map ? { __map: [...x.entries()] } : x));
}

export interface Fingerprint {
  graph: string;
  facts: string;
  files: number;
  /** a fixture the scanner refuses (no manifests) is fingerprinted by its error code */
  error?: string;
}

/**
 * Copy a fixture with LF line endings. The fingerprint must not depend on how git checked the
 * tree out (CRLF on a Windows autocrlf checkout, LF on Linux CI): a fixture's facts carry byte
 * offsets, so the same source read as CRLF fingerprints differently.
 */
export function copyFixtureLf(src: string, dest: string): void {
  fs.cpSync(src, dest, { recursive: true });
  const walk = (d: string): void => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.isFile()) {
        const buf = fs.readFileSync(p);
        if (buf.includes(0) || !buf.includes(13)) continue;
        fs.writeFileSync(p, buf.toString('utf8').replace(/\r\n/g, '\n'));
      }
    }
  };
  walk(dest);
}

/** Scan a COPY of the fixture (a scan must never write into the checked-in tree). */
export async function fingerprint(name: string): Promise<Fingerprint> {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'seq-oracle-'));
  try {
    const dir = path.join(tmp, name);
    copyFixtureLf(path.join(FIXTURES, name), dir);
    return await fingerprintDir(dir);
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

export async function fingerprintDir(dir: string, extra: Partial<ScanOptions> = {}): Promise<Fingerprint> {
  const all: FileFacts[] = [];
  let graph;
  try {
    graph = await scanRepo(dir, {
      ...extra,
      onServiceFacts: (per) => {
        for (const p of per) all.push(...p.facts);
      },
    });
  } catch (e) {
    return { graph: '', facts: '', files: 0, error: String((e as { code?: string }).code ?? (e as Error).message) };
  }
  const { scannedAt: _drop, ...rest } = graph as unknown as Record<string, unknown>;
  void _drop;
  // The scan root is a fresh temp dir each run; it is the only thing allowed to differ.
  const text = JSON.stringify(rest).split(JSON.stringify(dir).slice(1, -1)).join("<ROOT>");
  return { graph: sha(text), facts: sha(canon(all)), files: all.length };
}

test('oracle: every fixture scans byte-identically to the pre-2C golden', async () => {
  const names = fixtureNames();
  assert.ok(names.length >= 20, `derived only ${names.length} fixtures`);
  const got: Record<string, Fingerprint> = {};
  for (const n of names) got[n] = await fingerprint(n);
  if (process.env.SEQ_ORACLE_UPDATE === '1') {
    fs.writeFileSync(GOLDEN, JSON.stringify(got, null, 2) + '\n');
    return;
  }
  const golden = JSON.parse(fs.readFileSync(GOLDEN, 'utf8')) as Record<string, Fingerprint>;
  assert.deepStrictEqual(Object.keys(golden).sort(), names, 'golden and fixtures disagree on the set');
  for (const n of names) assert.deepStrictEqual(got[n], golden[n], `fixture ${n} drifted`);
  assert.ok(Object.values(got).reduce((a, f) => a + f.files, 0) > 50, 'oracle saw too few source files');
});

/* ---- the same oracle, through the parse pool ---------------------------------- */

import { extractFacts } from '../parse/facts.js';
import { initParser } from '../parse/treesitter.js';
import {
  PoolUnavailableError,
  WorkerParsePool,
  type FactsParsePool,
  type PooledFacts,
} from '../parse/parsePool.js';
import type { Lang } from '../types.js';

async function fingerprintWith(name: string, pool: FactsParsePool): Promise<Fingerprint> {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'seq-oracle-'));
  try {
    const dir = path.join(tmp, name);
    copyFixtureLf(path.join(FIXTURES, name), dir);
    return await fingerprintDir(dir, { parsePool: pool });
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

function goldenFor(name: string): Fingerprint {
  return (JSON.parse(fs.readFileSync(GOLDEN, 'utf8')) as Record<string, Fingerprint>)[name];
}

/** Finishes jobs in REVERSE submission order, so an order-dependent commit would show. */
class ReversingPool implements FactsParsePool {
  readonly inlineFirst = 0;
  readonly inflightLimit = 1000;
  private n = 0;
  async parse(src: string, rel: string, lang: Lang): Promise<PooledFacts> {
    await initParser();
    const mine = this.n++;
    const { lines: _l, ...facts } = extractFacts(src, rel, lang);
    void _l;
    await new Promise((r) => setTimeout(r, Math.max(0, 40 - mine * 4)));
    return facts;
  }
}

class DeadPool implements FactsParsePool {
  readonly inlineFirst = 0;
  readonly inflightLimit = 4;
  parse(): Promise<PooledFacts> {
    return Promise.reject(new PoolUnavailableError('test: pool is dead'));
  }
}

test('oracle: jobs finishing out of order still commit in walk order (every fixture)', async () => {
  for (const n of fixtureNames()) {
    assert.deepStrictEqual(await fingerprintWith(n, new ReversingPool()), goldenFor(n), `fixture ${n}`);
  }
});

test('oracle: a dead pool falls back to parsing on the scan thread (every fixture)', async () => {
  for (const n of fixtureNames()) {
    assert.deepStrictEqual(await fingerprintWith(n, new DeadPool()), goldenFor(n), `fixture ${n}`);
  }
});

test('oracle: real worker threads (every fixture, 3 workers, nothing parsed inline)', async () => {
  const file = path.resolve(here, '..', 'scan', 'scanWorker.js');
  assert.ok(fs.existsSync(file), `pool child program missing: ${file}`);
  const pool = new WorkerParsePool(file, 3, 0);
  try {
    let pooled = 0;
    const counting: FactsParsePool = {
      inlineFirst: 0,
      inflightLimit: pool.inflightLimit,
      parse: (s, r, l) => {
        pooled += 1;
        return pool.parse(s, r, l);
      },
    };
    for (const n of fixtureNames()) {
      assert.deepStrictEqual(await fingerprintWith(n, counting), goldenFor(n), `fixture ${n}`);
    }
    assert.ok(pooled > 50, `only ${pooled} files went through the workers`);
  } finally {
    await pool.close();
  }
});

test('oracle: a worker pool that cannot start (bad program file) degrades to inline parsing', async () => {
  const pool = new WorkerParsePool(path.join(os.tmpdir(), 'no-such-worker-file.js'), 2, 0);
  try {
    for (const n of ['shopfront', 'mixed-lang']) {
      assert.deepStrictEqual(await fingerprintWith(n, pool), goldenFor(n), `fixture ${n}`);
    }
  } finally {
    await pool.close();
  }
});
